// Some portions generated by Codex
package org.eclipse.rdf4j.http.client.jdk;

import static org.assertj.core.api.Assertions.assertThat;

import java.io.OutputStream;
import java.net.InetSocketAddress;
import java.net.URI;
import java.net.http.HttpClient;
import java.nio.charset.StandardCharsets;
import java.time.Duration;

import org.eclipse.rdf4j.http.client.spi.HttpRequest;
import org.eclipse.rdf4j.http.client.spi.HttpResponse;
import org.eclipse.rdf4j.http.client.spi.RDF4JHttpClientConfig;
import org.junit.jupiter.api.Test;

import com.sun.net.httpserver.HttpServer;

class JdkRDF4JHttpClientTimeoutTest {

	@Test
	void zeroResponseTimeoutDisablesConfiguredSocketTimeoutForTheRequest() throws Exception {
		HttpServer server = HttpServer.create(new InetSocketAddress("127.0.0.1", 0), 0);
		server.createContext("/delayed", exchange -> {
			try (exchange) {
				Thread.sleep(250);
				byte[] body = "ok".getBytes(StandardCharsets.UTF_8);
				exchange.sendResponseHeaders(200, body.length);
				try (OutputStream responseBody = exchange.getResponseBody()) {
					responseBody.write(body);
				}
			} catch (InterruptedException interrupted) {
				Thread.currentThread().interrupt();
			}
		});
		server.start();
		RDF4JHttpClientConfig config = RDF4JHttpClientConfig.newBuilder().socketTimeoutMs(100).build();
		JdkRDF4JHttpClient client = new JdkRDF4JHttpClient(HttpClient.newHttpClient(), config);
		try {
			HttpRequest request = HttpRequest.newBuilder("GET",
					URI.create("http://127.0.0.1:" + server.getAddress().getPort() + "/delayed"))
					.responseTimeout(Duration.ZERO)
					.build();
			try (HttpResponse response = client.execute(request)) {
				assertThat(response.getStatusCode()).isEqualTo(200);
				assertThat(response.getBodyAsStream().readAllBytes()).containsExactly('o', 'k');
			}
		} finally {
			client.close();
			server.stop(0);
		}
	}
}
